CREATE OR REPLACE FUNCTION public.audit_row_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_record_id uuid;
begin
  if tg_op = 'INSERT' then
    v_record_id := nullif((to_jsonb(new)->>'id'), '')::uuid;
    insert into public.audit_log(actor_type, table_name, record_id, action, after_data, source)
    values ('system', tg_table_name, v_record_id, 'insert', to_jsonb(new), 'database_trigger');
    return new;
  elsif tg_op = 'UPDATE' then
    v_record_id := nullif((to_jsonb(new)->>'id'), '')::uuid;
    insert into public.audit_log(actor_type, table_name, record_id, action, before_data, after_data, source)
    values ('system', tg_table_name, v_record_id, 'update', to_jsonb(old), to_jsonb(new), 'database_trigger');
    return new;
  elsif tg_op = 'DELETE' then
    v_record_id := nullif((to_jsonb(old)->>'id'), '')::uuid;
    insert into public.audit_log(actor_type, table_name, record_id, action, before_data, source)
    values ('system', tg_table_name, v_record_id, 'delete', to_jsonb(old), 'database_trigger');
    return old;
  end if;
  return null;
end;
$function$

CREATE OR REPLACE FUNCTION public.check_address_parent_source()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
begin
  if new.parent_address_id is not null and not exists (
    select 1 from public.address_registry parent
    where parent.id = new.parent_address_id and parent.source_id = new.source_id
  ) then
    raise exception 'Parent address must exist in the same source';
  end if;
  return new;
end;
$function$

