CREATE OR REPLACE FUNCTION public.prevent_ingestion_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
begin
  if old.raw_payload is distinct from new.raw_payload then
    raise exception 'raw_payload is immutable';
  end if;
  if old.source_hash is distinct from new.source_hash then
    raise exception 'source_hash is immutable';
  end if;
  if old.source_system is distinct from new.source_system then
    raise exception 'source_system is immutable';
  end if;
  if old.source_reference is distinct from new.source_reference then
    raise exception 'source_reference is immutable';
  end if;
  return new;
end;
$function$

